diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..549e1e3 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -2,6 +2,16 @@ import type { Provenance } from "./grade.ts";

 export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
   const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+
+  // In v0.1, "authored" claims in commit messages are self-asserted and
+  // cannot be trusted without cryptographic verification (signatures, key
+  // management). Trusting them allows attackers to forge authorship by
+  // setting arbitrary Author fields and claiming Provenance: authored.
+  //
+  // "inherited" and "reconstructed" describe message structure and can be
+  // safely determined from commit metadata, so they are trusted.
+  // A future signature scheme will verify "authored" status via trailers.
+
+  if (raw === "inherited" || raw === "reconstructed") return raw;
   return "unknown";
 };
